'use server'

import { cookies } from 'next/headers'
import { refresh } from 'next/cache'

export const NOTIFICATIONS_COOKIE = 'notifications'

export async function toggleNotifications() {
  const cookieStore = await cookies()
  const enabled = cookieStore.get(NOTIFICATIONS_COOKIE)?.value === 'on'

  cookieStore.set(NOTIFICATIONS_COOKIE, enabled ? 'off' : 'on', {
    httpOnly: true,
    sameSite: 'lax',
    path: '/',
  })

  // Refresh the current page in place — re-renders the route that called this
  // action without navigating anywhere. `refresh` is only valid inside a
  // Server Action.
  refresh()
}

